const CACHE='aventure-velo-v3-voyages';const FILES=['./','./index.html','./style.css','./engine.js','./app.js','./tile-art.js','./voyages.js','./assets/voyages/cards.png','./assets/tiles/plaine-0.webp','./assets/tiles/plaine-1.webp','./assets/tiles/plaine-2.webp','./assets/tiles/plaine-3.webp','./assets/tiles/montagne-0.webp','./assets/tiles/montagne-1.webp','./assets/tiles/montagne-2.webp','./assets/tiles/montagne-3.webp','./assets/tiles/ville-0.webp','./assets/tiles/ville-1.webp','./assets/tiles/ville-2.webp','./assets/tiles/ville-3.webp','./assets/tiles/cote-0.webp','./assets/tiles/cote-1.webp','./assets/tiles/cote-2.webp','./assets/tiles/cote-3.webp','./manifest.json','./icon.svg','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===self.location.origin)e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));});
